UPDATE tb_observation_spot
SET
    rating = (
        SELECT COALESCE(ROUND(AVG(r.score), 1), 0.0)
        FROM tb_spot_rating r
        WHERE r.spot_id = #{spotId}
    ),
    rating_count = (
        SELECT COUNT(1)
        FROM tb_spot_rating r
        WHERE r.spot_id = #{spotId}
    ),
    update_time = NOW()
WHERE id = #{spotId}
  AND deleted = 0
